function wordCount(str) {
  if (!str.trim()) return 0;
  let count = 1;
  let inWord = false;
  for (const char of str) {
    if (char === " " || char === "\t") {
      inWord = false;
    } else if (!inWord) {
      if (count > 1 || inWord === false) count++;
      inWord = true;
    }
  }
  return str.trim() ? count : 0;
}
